  let dark_a = clamp(bottom * uniforms.intensity * 0.22, 0.0, 1.0);
  let total_a = clamp(dark_a + light_a * (1.0 - dark_a), 0.0, 1.0);
  let rgb = select(vec3f(0.0), vec3f(light_a / total_a), total_a > 0.001);
